mapper.select:
SELECT ,
       EXISTS (
           SELECT 1
           FROM favorites f
           WHERE f.user_id = #{userId,jdbcType=BIGINT}
             AND f.place_id = places.place_id
       ) AS favorite
FROM places

    is_active = TRUE

        AND (name ILIKE CONCAT('%', #{keyword}, '%')
            OR region ILIKE CONCAT('%', #{keyword}, '%')
            OR city ILIKE CONCAT('%', #{keyword}, '%'))


        AND category = #{category}


        AND region = #{region}


        AND EXISTS (
            SELECT 1
            FROM place_travel_styles pts
            WHERE pts.place_id = places.place_id
              AND pts.travel_style_id = #{styleId}
        )


ORDER BY favorite DESC, average_rating DESC, place_id DESC
LIMIT #{size} OFFSET #{offset}
